@import url('https://fonts.googleapis.com/css2?family=Hanken+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Stripe DNA — clean white, indigo/cyan gradient accents, crisp small type, airy depth */
.theme-stripe-dna {
  --bg: oklch(0.981 0.005 247.9);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.975 0.008 265);
  --fg: oklch(0.22 0.03 270);
  --fg-muted: oklch(0.52 0.03 270);
  --accent: oklch(0.521 0.268 277.4);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.690 0.206 40.4);
  --line: oklch(0.9 0.012 270);
  --success: oklch(0.66 0.16 155);
  --warning: oklch(0.78 0.15 75);
  --danger: oklch(0.6 0.21 22);

  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.875rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0.3 0.06 270 / 8%), 0 1px 1px oklch(0.3 0.06 270 / 4%);
  --shadow-2: 0 4px 12px -2px oklch(0.3 0.06 270 / 12%), 0 2px 4px -2px oklch(0.3 0.06 270 / 8%);
  --shadow-3: 0 24px 48px -16px oklch(0.3 0.06 270 / 22%), 0 8px 16px -8px oklch(0.3 0.06 270 / 12%);
  --glow: 0 0 0 3px color-mix(in oklab, var(--accent) 22%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Hanken Grotesk", "Inter", sans-serif;
  --font-body: "Hanken Grotesk", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.03em;
  --label-transform: none;
  --label-tracking: 0.01em;

  background-color: var(--bg);
  background-image:
    radial-gradient(120% 70% at 8% -10%, oklch(0.53 0.21 275 / 12%) 0%, transparent 60%),
    radial-gradient(90% 60% at 95% -5%, oklch(0.72 0.14 205 / 14%) 0%, transparent 55%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-stripe-dna h1,
.theme-stripe-dna h2,
.theme-stripe-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 700;
}

.theme-stripe-dna h1 {
  background-image: linear-gradient(
    100deg,
    oklch(0.22 0.03 270) 20%,
    oklch(0.53 0.21 275) 55%,
    oklch(0.72 0.14 205) 90%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* signature */
.theme-stripe-dna { --font-ui: var(--font-display); }
.theme-stripe-dna h1 { background: linear-gradient(95deg, #533afd, #fb76fa 55%, #ff6118); -webkit-background-clip: text; background-clip: text; color: transparent; }
.theme-stripe-dna button { background-image: linear-gradient(95deg, var(--accent), color-mix(in oklab, var(--accent) 60%, #fb76fa)); border-color: transparent; }

/* depth */
.theme-stripe-dna thead th { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 600; color: var(--fg-muted); background: var(--surface-2); border-bottom: 1px solid var(--line); }
.theme-stripe-dna td { border-bottom: 1px solid color-mix(in oklab, var(--line) 60%, transparent); font-variant-numeric: tabular-nums; }
.theme-stripe-dna tbody tr:hover { background: color-mix(in oklab, var(--accent) 4%, var(--surface)); }
.theme-stripe-dna a { color: var(--accent); text-decoration: none; font-weight: 500; }
.theme-stripe-dna a:hover { color: color-mix(in oklab, var(--accent) 75%, var(--fg)); }
.theme-stripe-dna input, .theme-stripe-dna select, .theme-stripe-dna textarea { border: 1px solid var(--line); background: var(--surface); box-shadow: 0 1px 1px oklch(0.3 0.06 270 / 6%); transition: border-color 120ms ease, box-shadow 120ms ease; }
.theme-stripe-dna input:focus-visible, .theme-stripe-dna select:focus-visible, .theme-stripe-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-stripe-dna kbd { font-family: var(--font-mono); font-size: 0.75em; padding: 0.1em 0.45em; background: var(--surface); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: var(--radius-sm); }
.theme-stripe-dna ::selection { background: oklch(0.53 0.21 275 / 22%); }
.theme-stripe-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-stripe-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-stripe-dna ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--fg-muted) 35%, transparent); border-radius: var(--radius-pill); }
.theme-stripe-dna .label-caps { color: var(--fg-muted); font-weight: 600; }
.theme-stripe-dna .themed-border { background-image: linear-gradient(95deg, #533afd, #fb76fa 55%, #ff6118); background-size: 100% 3px; background-repeat: no-repeat; background-position: top; }
.theme-stripe-dna button[role="tab"] { background-image: none; }
.theme-stripe-dna button[role="tab"][data-state="active"] { background-image: linear-gradient(95deg, var(--accent), color-mix(in oklab, var(--accent) 60%, #fb76fa)); color: var(--accent-fg); }
.theme-stripe-dna button { transition: transform 120ms ease, box-shadow 120ms ease, filter 120ms ease; }
.theme-stripe-dna button:hover { filter: brightness(1.06); box-shadow: var(--shadow-2); }
.theme-stripe-dna button:active { transform: translateY(1px); filter: brightness(0.97); }

/* alt mode: auto-derived dark variant */
.theme-stripe-dna.alt-mode {
  --bg: oklch(0.145 0.005 247.9);
  --surface: oklch(0.185 0.005 247.9);
  --surface-2: oklch(0.225 0.005 247.9);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.618 0.235 277.4);
  background-image:
    radial-gradient(120% 70% at 8% -10%, oklch(0.45 0.2 275 / 26%) 0%, transparent 60%),
    radial-gradient(90% 60% at 95% -5%, oklch(0.6 0.13 205 / 18%) 0%, transparent 55%);
  background-attachment: fixed;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
